import re, sys, os
from pathlib import Path
root = Path(sys.argv[1])
skip = ("docs/evaluations", "dist/", "node_modules", ".cursor", ".opencode", ".gemini", "harnesses/", "CHANGELOG.md", "tests/", ".agents", "/.claude/")
pat = re.compile(r"(?:shared|docs|scripts|tools|plugins)/[A-Za-z0-9_./@<>-]+\.(?:md|json|py|sh)")
seen = set()
for p in root.rglob("*"):
    if not p.is_file() or p.suffix not in (".md", ".json", ".py", ".sh"):
        continue
    rel = str(p.relative_to(root))
    if any(s in rel or rel.startswith(s) for s in skip) or p.is_symlink():
        continue
    if rel.startswith(".claude/"):
        continue
    try:
        text = p.read_text(encoding="utf-8")
    except Exception:
        continue
    for i, line in enumerate(text.splitlines(), 1):
        for m in pat.finditer(line):
            ref = m.group(0).rstrip(".")
            if "<" in ref or "*" in ref:
                continue
            if (root / ref).exists():
                continue
            # relative to plugin root
            if rel.startswith("plugins/"):
                plugin = rel.split("/")[1]
                if (root / "plugins" / plugin / ref).exists():
                    continue
            key = (rel, i, ref)
            if key not in seen:
                seen.add(key)
                print(f"{rel}:{i}: {ref}")

